#!/usr/bin/env bash
# No dotenv: credentials are generated by test-db-up and remain in this shell.
set -euo pipefail
export PATH="/usr/bin:/mingw64/bin:$PATH"
cd "$(dirname "$0")/../../.."
mkdir -p output/notify-tx-1023
redis_name=""
cleanup() {
  local rc=$?
  trap - EXIT
  if [[ -n "$redis_name" ]]; then
    if [[ "$redis_name" =~ ^codex-notify-redis-[a-f0-9]{12}$ ]] &&
       [[ "$(docker inspect --format '{{ index .Config.Labels "pilingtrack.codex.notify-test" }}' "$redis_name" 2>/dev/null)" == "1" ]]; then
      docker rm -fv "$redis_name" >>output/notify-tx-1023/cleanup.log 2>&1 || true
    fi
  fi
  if [[ -n "${INTEGRATION_DB_CONTAINER:-}" ]]; then
    bash scripts/test-db-down.sh "$INTEGRATION_DB_CONTAINER" >>output/notify-tx-1023/cleanup.log 2>&1 || true
  fi
  exit "$rc"
}
trap cleanup EXIT
exports="$(bash scripts/test-db-up.sh 2>output/notify-tx-1023/postgres.log)"
eval "$exports"
unset exports
redis_name="codex-notify-redis-$(node -e "process.stdout.write(require('node:crypto').randomBytes(6).toString('hex'))")"
docker run -d --name "$redis_name" --label pilingtrack.codex.notify-test=1 -p 127.0.0.1::6379 redis:7-alpine redis-server --maxmemory 64mb --maxmemory-policy noeviction >output/notify-tx-1023/redis.log
port="$(docker port "$redis_name" 6379/tcp)"; port="${port##*:}"
export REDIS_URL="redis://127.0.0.1:$port"
export REDIS_URL_CACHE="$REDIS_URL"
export DATABASE_URL="$INTEGRATION_DATABASE_URL_APP"
export DATABASE_URL_POSTGRES="$INTEGRATION_DATABASE_URL_APP"
export DEFAULT_TENANT_ID="notify-b-disposable"
export PRISMA_CONNECTION_LIMIT=8
export LOG_LEVEL=error
npx --no-install prisma generate --config prisma.integration.config.ts >output/notify-tx-1023/generate.log 2>&1
node --test tests/integration/notifications/measurements.test.mjs >output/notify-tx-1023/measurement-after.tap 2>&1
printf '0\n' >output/notify-tx-1023/measurement-after.exit
set +e
node --test --test-concurrency=1 tests/integration/notifications/delivery.integration.mjs >output/notify-tx-1023/integration.tap 2>&1
rc=$?
set -e
printf '%s\n' "$rc" >output/notify-tx-1023/integration.exit
exit "$rc"
